which node && node -e "
const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
// Search for Daniel Ortiz in the raw binary
const str = data.toString('utf8');
const idx = str.indexOf('Daniel Ortiz');
if (idx !== -1) {
  // Print surrounding context
  const start = Math.max(0, idx - 200);
  const end = Math.min(str.length, idx + 300);
  const chunk = data.slice(start, end).toString('utf8').replace(/[^\x20-\x7E\n\r\t]/g, ' ');
  console.log(chunk);
}
"

node -e "
const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
const str = data.toString('utf8');

// Find all occurrences of Daniel Ortiz with more context
let idx = 0;
while ((idx = str.indexOf('Daniel Ortiz', idx)) !== -1) {
  const start = Math.max(0, idx - 50);
  const end = Math.min(str.length, idx + 200);
  const chunk = data.slice(start, end).toString('utf8').replace(/[^\x20-\x7E]/g, '|');
  console.log('--- Match at offset', idx, '---');
  console.log(chunk);
  console.log();
  idx += 1;
}
"
